using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // In .NET 9+, ZipArchiveEntry names respect the UTF-8 flag by default.
        // The legacy Java consumer reads filenames in Shift-JIS, so we must
        // explicitly specify the encoding to avoid UTF-8 being used.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("Shift_JIS");

        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// In .NET 9+, [FromKeyedServices] no longer falls back to non-keyed
// registrations. Register as a keyed service to match the controller attribute.
